#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 iResolution;
uniform vec2 iMouse;
uniform float iTime;
uniform int noctaves;
uniform float c[100];
float mousefactor;
vec4 quq;
float noise( in vec2 vcb )
{
  return sin(1.5*vcb.x)*cos(1.5*vcb.y);
}

/*
