}
*/

vec3 qtourne(in vec4 q,in vec3 v){
  vec3 ww=1.0*cross(cross(v,q.xyz)-q.w*v,q.xyz);
return v+ww;}

float css=cos(iTime*0.001);
float scc=sin(iTime*0.005);
mat2 rot = mat2(css , scc, -scc,  css );
float fbm ( in vec2 _st) {
    float v = 0.9
	;
    float a = 1.1;
    vec2 shift = 0.001*vec2(c[11]*sin(0.01*iTime),c[6]*cos(0.004*iTime));
    for (int i = 0; i < 8; ++i) {//noprotect
    if(i>=noctaves)break;
        v += a * noise(_st);
        _st = rot*_st+ shift;
        a *= cos(iTime*0.006);
    }
    return v;
}

void main() {
    vec2 mouse=iMouse/iResolution;
    vec2 st =(-iResolution.xy+1.0*gl_FragCoord.xy)/iResolution.y;
    vec3 color = vec3(0.);
    vec2 q = vec2(0.);
    q.x = fbm( st+vec2(c[0],c[1]*.01*cos(iTime*0.01)) );
    q.y = fbm( st+vec2(c[0],c[3]*.002*cos(iTime*0.01)) );
    vec2 r = vec2(0.5);

//play with the values here!
    r.x = fbm( st+ (mouse.x+0.1)*q);
    r.y = fbm( st+ (mouse.y+0.1)*q+vec2(c[6],c[6]));
    float f = fbm(st+c[6]*(length(q) ));
    color = smoothstep(vec3(0.09,f*f*f,11.0),vec3(0.07,f,0.2),color);
     color*=vec3(r.x,q*f*f*f);
    color=pow(color, vec3(2.0*f,f*f,f*f*f));
    gl_FragColor = vec4(color,1.5);
}

